#include "PluginProcessor.h"
#include "PluginEditor.h"
#include "BuiltinEffects.h"
#include <stdexcept>
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void good(const drum::Result& result){if(!result.ok)throw std::runtime_error(result.message.toStdString());}
void pump(){juce::MessageManager::getInstance()->runDispatchLoopUntil(40);juce::Timer::callPendingTimersSynchronously();}
drum::Instrument sound(DrumAudioProcessor& p){auto s=p.getLibrary().snapshot();return drum::activeKit(s)->groups[0].instruments[0];}
void shot(DrumAudioProcessor& p,float expected){p.getSampleEngine().stop();juce::AudioBuffer<float> audio(2,256);juce::MidiBuffer midi;p.processBlock(audio,midi);midi.addEvent(juce::MidiMessage::noteOn(1,21,(juce::uint8)127),0);p.processBlock(audio,midi);check(std::abs(audio.getSample(0,100)-expected)<.001f,"MIDI track playback changed with library view");}
void capture(juce::Component& editor,const char* name){auto f=juce::File::getCurrentWorkingDirectory().getChildFile(name);f.deleteFile();juce::FileOutputStream output(f);check(juce::PNGImageFormat().writeImageToStream(editor.createComponentSnapshot(editor.getLocalBounds()),output),"Track screenshot failed");}
}
void runTrackLibraryTests(){
    // Independent edits to different kits merge; concurrent edits to one kit never overwrite.
    auto file=juce::File::getCurrentWorkingDirectory().getChildFile("merge-"+juce::Uuid().toString()+"/kits.xml");drum::GlobalKitStore seed(file),a(file),b(file),observer(file);drum::KitLibrary initial,left,right,latest;good(seed.load(initial));auto k0=initial.snapshot().activeKit,k1=initial.addKit().id;good(seed.save(initial));good(a.load(left));good(b.load(right));good(left.rename(k0,"Kicks"));good(right.rename(k1,"Percussion"));good(a.save(left));good(b.save(right));good(observer.load(latest));auto merged=latest.snapshot();check(merged.kits[0].name=="Kicks" && merged.kits[1].name=="Percussion","Separate library edits did not merge");auto before=file.loadFileAsString();good(left.rename(k1,"Conflicting change"));check(!a.save(left).ok && file.loadFileAsString()==before,"Concurrent kit edit overwrote shared library");
    good(a.load(left));good(b.load(right));good(left.removeKit(k1));good(a.save(left));good(right.rename(k1,"Deleted elsewhere"));before=file.loadFileAsString();check(!b.save(right).ok && file.loadFileAsString()==before,"Deleted kit was silently resurrected");
    auto corrupt=file.getSiblingFile("broken.xml");corrupt.replaceWithText("broken library");drum::GlobalKitStore broken(corrupt);check(!broken.load(latest).ok && corrupt.loadFileAsString()=="broken library","Corrupt library was overwritten");
    DrumAudioProcessor track(true),second(true);track.setRateAndBufferSizeDetails(48000,256);track.prepareToPlay(48000,256);second.setRateAndBufferSizeDetails(48000,256);second.prepareToPlay(48000,256);
    good(track.openSharedLibrary());auto& editor=*track.libraryEditorProcessor();auto state=editor.getLibrary().snapshot();auto kit=state.activeKit,group=drum::activeKit(state)->groups[0].id;auto instrument=editor.getLibrary().addInstrument(kit,group).id;good(editor.getLibrary().rename(kit,"Shared drums"));
    editor.getSampleEngine().requestLoad(kit,instrument,juce::File::getCurrentWorkingDirectory().getChildFile("playback-test-data/mono.wav"));check(editor.getSampleEngine().waitForLoading(10000),"Shared sample load failed");
    auto description=drum::builtinDescription(drum::BuiltinKind::utility);drum::BuiltinEffect utility(drum::BuiltinKind::utility);utility.controls[0]->setValueNotifyingHost(utility.controls[0]->convertTo0to1(-6.0206f));juce::MemoryBlock fx;utility.getStateInformation(fx);good(editor.getLibrary().setEffects(kit,instrument,{{juce::Uuid().toString(),description.createXml()->toString(),fx.toBase64Encoding(),false}}));good(editor.saveSharedLibrary());good(editor.useLibrarySound(kit,instrument));
    good(second.openSharedLibrary());auto& other=*second.libraryEditorProcessor();good(other.useLibrarySound(kit,instrument));auto one=sound(track),two=sound(second);check(one.id!=two.id && one.id!=instrument && one.effects[0].id!=two.effects[0].id,"Track copies share identities");check(one.note==21 && two.note==21,"Tracks do not have independent keyboard maps");
    track.getEffects().sync();second.getEffects().sync();check(track.getSampleEngine().waitForLoading(10000) && second.getSampleEngine().waitForLoading(10000),"Copied sample did not load");shot(track,.125f);shot(second,.125f);
    auto controls=one.controls;controls.volumeDb=-6.0206;auto target=track.getLibrary().snapshot();good(track.getLibrary().setControls(target.activeKit,one.id,controls));check(track.getSampleEngine().waitForLoading(10000),"Track control change timeout");check(sound(second).controls.volumeDb==0 && sound(editor).controls.volumeDb==0,"Track edits changed source or another track");shot(track,.0625f);
    auto blank=editor.getLibrary().addKit().id;pump();shot(track,.0625f); // Library selection must not redirect incoming MIDI.
    juce::MemoryBlock saved;track.getStateInformation(saved);auto sharedFile=drum::GlobalKitStore::defaultFile();auto sharedBefore=sharedFile.loadFileAsString();DrumAudioProcessor recalled(true);recalled.setStateInformation(saved.getData(),(int)saved.getSize());pump();check(sharedFile.loadFileAsString()==sharedBefore,"Project recall rewrote global kits");check(sound(recalled).controls.volumeDb==controls.volumeDb && sound(recalled).effects[0].state==one.effects[0].state,"Track recall lost independent sound settings");
    good(editor.getLibrary().activateKit(kit));DrumAudioProcessorEditor mainView(track),libraryView(editor);mainView.setSize(1000,750);libraryView.setSize(1000,750);capture(mainView,"drum-midi-track.png");capture(libraryView,"drum-shared-library.png");
    // Legacy kits are retained globally, while the active kit becomes a local track.
    DrumAudioProcessor legacy;auto old=legacy.getLibrary().snapshot();auto oldKit=old.activeKit,oldGroup=old.kits[0].groups[0].id;good(legacy.getLibrary().addInstrument(oldKit,oldGroup));good(legacy.getLibrary().addKit(true));juce::MemoryBlock oldState;legacy.getStateInformation(oldState);DrumAudioProcessor migrated(true);migrated.setStateInformation(oldState.getData(),(int)oldState.getSize());auto local=migrated.getLibrary().snapshot();check(local.kits.size()==1 && local.kits[0].groups.size()==1 && drum::instrumentCount(local.kits[0])==12,"Legacy active kit did not become one MIDI track");pump();check(migrated.libraryStatus().isNotEmpty(),"Legacy migration did not report status");
}
